mapper.sql:
FROM catalog_search_documents d
JOIN catalog_search_state s ON s.singleton_id=1 AND s.generation=d.generation
JOIN products p ON p.id=d.product_id AND p.lifecycle_status='ACTIVE'
WHERE (d.locale=#{locale} OR (d.locale='' AND NOT EXISTS (
  SELECT 1 FROM catalog_search_documents t
  WHERE t.generation=d.generation AND t.product_id=d.product_id AND t.locale=#{locale}
)))
AND d.merchant_id IN
#{merchant}
AND d.unit_price >= #{minPrice}
AND d.unit_price <= #{maxPrice}

  AND LOCATE(#{term},d.searchable)>0

mapper.select:
SELECT 1 AS schema_version,d.product_id,d.merchant_id,d.name,d.brief,d.description,
  d.unit_price,p.image_url,p.thumbnail_url,p.lifecycle_status,d.business_version,p.updated_at

ORDER BY

  d.unit_price ASC,
  d.unit_price DESC,

    NULLIF(FIELD(d.product_id,
    #{rated}
    ),0) IS NULL,
    FIELD(d.product_id,
    #{rated}
    ) ASC,


    (LOCATE(#{terms[0]},d.name)>0) DESC,
    MATCH(d.searchable) AGAINST (#{query} IN NATURAL LANGUAGE MODE) DESC,


d.product_id ASC LIMIT #{size} OFFSET #{offset}
